            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.displayName").value("Franklin, George"));
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerDuplicateTelephoneReturnsConflict() throws Exception {
        Owner existing = new Owner();
        existing.setFirstName("Jane");
        existing.setLastName("Doe-" + System.nanoTime());
        existing.setAddress("110 W. Liberty St.");
        existing.setCity("Madison");
        existing.setTelephone("6081234567");
        ownerRepository.save(existing);

        // A differently-formatted telephone that normalizes to the same digits must be rejected.
        String body = """
            {"firstName":"John","lastName":"Roe","address":"1 Main St.","city":"Madison","telephone":"(608) 123-4567"}
            """;
        mvc.perform(post("/api/owners").content(body)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isConflict());
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerRejectedWhenCityAtCapacity() throws Exception {
        // Fill a city to exactly 50 owners; the next owner in that city must be rejected.
        String city = "Capville-" + System.nanoTime();
        for (int i = 0; i < 50; i++) {
            Owner owner = new Owner();
            owner.setFirstName("Resident" + i);
            owner.setLastName("Resident-" + System.nanoTime());
            owner.setAddress(i + " Cap St.");
            owner.setCity(city);
            owner.setTelephone("60800" + String.format("%05d", i));
            ownerRepository.save(owner);
        }

        String body = """
            {"firstName":"George","lastName":"Newcomer","address":"9000 Cap St.","city":"%s","telephone":"6089990000"}
            """.formatted(city);
        mvc.perform(post("/api/owners").content(body)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isConflict());
    }

